css:
.copan-sim-container {
    padding: 28px;
    background: linear-gradient(170deg, #0b1e18 0%, #132e24 40%, #1a3a2e 100%);
    min-height: 100vh;
    font-family: 'Georgia', 'Palatino Linotype', serif;
    color: #d4ddd8;
}
.copan-sim-header {
    background: linear-gradient(135deg, #1b4332 0%, #2d6a4f 60%, #40916c 100%);
    border-radius: 16px;
    padding: 36px 32px 28px;
    text-align: center;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
    box-shadow: 0 8px 32px rgba(0,0,0,0.35);
}
.copan-sim-header::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M30 5 L55 30 L30 55 L5 30Z' fill='none' stroke='rgba(212,168,83,0.08)' stroke-width='1'/%3E%3C/svg%3E") repeat;
    pointer-events: none;
}
.copan-sim-header-badge {
    display: inline-block;
    background: rgba(212,168,83,0.2);
    border: 1px solid rgba(212,168,83,0.4);
    color: #d4a853;
    font-size: 0.72rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    padding: 5px 16px;
    border-radius: 20px;
    margin-bottom: 14px;
    font-family: -apple-system, 'Segoe UI', sans-serif;
    position: relative;
}
.copan-sim-header h1 {
    color: #ffffff;
    font-size: 1.65rem;
    font-weight: 700;
    margin: 0 0 6px;
    position: relative;
}
.copan-sim-subtitle {
    color: rgba(255,255,255,0.6);
    font-size: 0.9rem;
    margin: 0;
    font-style: italic;
    position: relative;
}
.copan-sim-period-counter {
    text-align: center;
    font-family: -apple-system, 'Segoe UI', sans-serif;
    font-size: 0.85rem;
    color: #8faa9d;
    margin-bottom: 24px;
    letter-spacing: 0.06em;
}
.copan-sim-period-counter span {
    margin: 0 3px;
}
.copan-sim-period-counter #currentDay,
.copan-sim-period-counter #maxPeriods {
    color: #d4a853;
    font-weight: 700;
    font-size: 1.05rem;
}
.copan-sim-briefing {
    background: rgba(212,168,83,0.06);
    border: 1px solid rgba(212,168,83,0.2);
    border-left: 4px solid #d4a853;
    border-radius: 12px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.copan-sim-briefing-icon {
    font-size: 1.3rem;
    margin-bottom: 8px;
}
.copan-sim-briefing-heading {
    color: #d4a853;
    font-size: 1.05rem;
    font-weight: 700;
    margin: 0 0 10px;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.copan-sim-briefing-text {
    color: #c4d1cb;
    font-size: 0.88rem;
    line-height: 1.65;
}
.copan-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}
.copan-sim-kpi-card {
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 20px 16px;
    text-align: center;
    position: relative;
    overflow: hidden;
    transition: transform 0.2s ease, background 0.2s ease;
}
.copan-sim-kpi-card:hover {
    transform: translateY(-3px);
    background: rgba(255,255,255,0.07);
}
.copan-sim-kpi-card::after {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 3px;
}
.copan-sim-kpi-reputation::after { background: linear-gradient(90deg, #d4a853, #f0c674); }
.copan-sim-kpi-cash::after { background: linear-gradient(90deg, #52b788, #74c69d); }
.copan-sim-kpi-sentiment::after { background: linear-gradient(90deg, #5390d9, #6ca0dc); }
.copan-sim-kpi-bookings::after { background: linear-gradient(90deg, #9b5de5, #b185db); }
.copan-sim-kpi-icon {
    font-size: 1.5rem;
    margin-bottom: 6px;
}
.copan-sim-kpi-label {
    color: #8faa9d;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.copan-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #ffffff;
}
.copan-sim-kpi-reputation .copan-sim-kpi-value { color: #f0c674; }
.copan-sim-kpi-cash .copan-sim-kpi-value { color: #74c69d; }
.copan-sim-kpi-sentiment .copan-sim-kpi-value { color: #6ca0dc; }
.copan-sim-kpi-bookings .copan-sim-kpi-value { color: #b185db; }
.copan-sim-controls {
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 14px;
    padding: 28px;
    margin-bottom: 24px;
}
.copan-sim-controls h3 {
    color: #d4a853;
    font-size: 1rem;
    font-weight: 700;
    margin: 0 0 20px;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.copan-sim-control-row {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 20px;
    margin-bottom: 20px;
}
.copan-sim-control-group label {
    display: block;
    color: #8faa9d;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 8px;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.copan-sim-select,
.copan-sim-controls input[type="number"] {
    width: 100%;
    background: #0b1e18;
    border: 1px solid rgba(212,168,83,0.25);
    color: #d4ddd8;
    border-radius: 8px;
    padding: 10px 14px;
    font-size: 0.9rem;
    font-family: -apple-system, 'Segoe UI', sans-serif;
    transition: border-color 0.2s ease;
}
.copan-sim-select:focus,
.copan-sim-controls input[type="number"]:focus {
    outline: none;
    border-color: #d4a853;
    box-shadow: 0 0 0 3px rgba(212,168,83,0.15);
}
.copan-sim-select option {
    background: #0b1e18;
    color: #d4ddd8;
}
.copan-sim-input-hint {
    display: block;
    color: #6b8a7d;
    font-size: 0.72rem;
    margin-top: 5px;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.copan-sim-btn-group {
    display: flex;
    gap: 12px;
}
.copan-sim-btn-primary {
    background: linear-gradient(135deg, #d4a853, #c4933f);
    color: #0b1e18;
    border: none;
    border-radius: 8px;
    padding: 12px 32px;
    font-size: 0.9rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    cursor: pointer;
    transition: transform 0.15s ease, box-shadow 0.2s ease;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.copan-sim-btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(212,168,83,0.35);
}
.copan-sim-btn-secondary {
    background: transparent;
    color: #8faa9d;
    border: 1px solid rgba(143,170,157,0.3);
    border-radius: 8px;
    padding: 12px 20px;
    font-size: 0.82rem;
    cursor: pointer;
    transition: border-color 0.2s ease;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.copan-sim-btn-secondary:hover {
    border-color: #8faa9d;
    color: #d4ddd8;
}
.copan-sim-chart-section,
.copan-sim-history-section {
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
}
.copan-sim-chart-section h3,
.copan-sim-history-section h3 {
    color: #d4a853;
    font-size: 0.95rem;
    font-weight: 700;
    margin: 0 0 16px;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.copan-sim-chart-wrap {
    position: relative;
    height: 280px;
}
.copan-sim-history-section .table {
    color: #c4d1cb;
    font-size: 0.82rem;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.copan-sim-history-section .table th {
    color: #8faa9d;
    border-color: rgba(255,255,255,0.08);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.copan-sim-history-section .table td {
    border-color: rgba(255,255,255,0.05);
}
@media (max-width: 768px) {
    .copan-sim-container { padding: 16px; }
    .copan-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); gap: 10px; }
    .copan-sim-control-row { grid-template-columns: 1fr; }
    .copan-sim-header h1 { font-size: 1.3rem; }
    .copan-sim-kpi-value { font-size: 1.3rem; }
    .copan-sim-btn-group { flex-direction: column; }
}

/* ---- End-of-simulation debrief (v1.1.0) ---------------------------------- */
.copan-cm { text-align:center; color:#d4dcd7; font-family:-apple-system,'Segoe UI',sans-serif; padding:8px 4px 4px; }
.copan-cm-title { color:#f0c674; font-size:1.3rem; font-weight:800; margin-bottom:16px; }
.copan-cm-score-ring { width:126px; height:126px; margin:0 auto 12px; border:6px solid #f0c674; border-radius:50%;
    display:flex; flex-direction:column; align-items:center; justify-content:center; background:rgba(20,30,26,0.6); box-shadow:0 0 20px rgba(240,198,116,0.15); }
.copan-cm-score { font-size:2.6rem; font-weight:800; line-height:1; }
.copan-cm-score-max { font-size:0.76rem; color:#8faa9d; }
.copan-cm-verdict { font-size:1.2rem; font-weight:700; margin-bottom:4px; }
.copan-cm-grade { font-size:0.9rem; color:#8faa9d; font-weight:600; }
.copan-cm-metrics { display:flex; justify-content:center; flex-wrap:wrap; gap:12px; margin:18px 0 6px; }
.copan-cm-metric { background:rgba(255,255,255,0.04); border:1px solid rgba(143,170,157,0.25); border-radius:12px; padding:13px 16px; min-width:110px; }
.copan-cm-metric-label { color:#8faa9d; font-size:0.64rem; text-transform:uppercase; letter-spacing:0.07em; margin-bottom:6px; }
.copan-cm-metric-value { font-size:1.1rem; font-weight:700; color:#eef2ef; }
.copan-cm-insights { text-align:left; background:rgba(255,255,255,0.03); border:1px solid rgba(143,170,157,0.25); border-left:3px solid #f0c674; border-radius:10px; padding:15px 20px; margin-top:16px; }
.copan-cm-insights-title { color:#f0c674; font-size:0.74rem; text-transform:uppercase; letter-spacing:0.07em; margin-bottom:9px; font-weight:700; }
.copan-cm-insights ul { margin:0; padding-left:20px; }
.copan-cm-insights li { color:#d4dcd7; font-size:0.9rem; line-height:1.55; margin-bottom:7px; }
.copan-cm-insights li:last-child { margin-bottom:0; }

