        _t(key, vars) {
            try { if (window.mySimulation && typeof window.mySimulation.t === 'function') return window.mySimulation.t(key, vars); } catch (e) {}
            return key;
        }
        _lang() {
            try {
                var m = window.mySimulation || {};
                var l = m.lang || m.currentLanguage || m.language || (window.vcI18n && (window.vcI18n.lang || window.vcI18n.currentLanguage)) || 'en';
                return (String(l).toLowerCase().indexOf('es') === 0) ? 'es' : 'en';
            } catch (e) { return 'en'; }
        }
        _computeScore(rep, sent, book, totalSpent) {
            var score = 0;
            if (rep >= 4.7) score += 30; else if (rep >= 4.5) score += 20; else if (rep >= 4.2) score += 10;
            if (sent >= 70) score += 25; else if (sent >= 50) score += 15; else if (sent >= 30) score += 5;
            if (book >= 85) score += 25; else if (book >= 75) score += 15; else if (book >= 60) score += 5;
            if (totalSpent <= 50000) score += 20; else if (totalSpent <= 80000) score += 10;
            return Math.max(0, Math.min(100, score));
        }
        _tierFor(score) { if (score >= 80) return 'excellent'; if (score >= 60) return 'good'; if (score >= 40) return 'adequate'; return 'needs_improvement'; }
        _gradeFor(score) { if (score >= 85) return 'A'; if (score >= 70) return 'B'; if (score >= 55) return 'C'; if (score >= 40) return 'D'; return 'F'; }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 200000,
                    reputationTA: 4.60,
                    reputationGoogle: 4.30,
                    socialSentiment: 35,
                    bookingsNextMonth: 75,
                    totalRecoveryCost: 0,
                    reputationHistory: [],
                    bookingHistory: [],
                    sentimentHistory: [],
                    performance: { overallScore: 0, grade: 'F', tier: 'needs_improvement' },
                    _snap: {}
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    strategy: 'A',
                    budget: 5000
                };
            }

            var self = this;
            var onLang = function() { try { self._updateBriefing(window.mySimulation.state); } catch (e) {} };
            try { if (window.mySimulation && window.mySimulation.eventBus && typeof window.mySimulation.eventBus.on === 'function') window.mySimulation.eventBus.on('language:changed', onLang); } catch (e) {}
            try { document.addEventListener('express:langchanged', onLang); } catch (e) {}

            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var strategyEl = document.getElementById('strategySelect');
            if (strategyEl) decisions.strategy = strategyEl.value;

            var budgetEl = document.getElementById('budgetInput');
            if (budgetEl) decisions.budget = parseFloat(budgetEl.value) || 0;

            if (decisions.budget < 0 || decisions.budget > 25000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }

            var currentState = window.mySimulation.state;
            if (decisions.budget > currentState.domainState.cash) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('insufficient_funds'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            if (!ds._snap) ds._snap = {};
            if (ds._snap[round]) { var _s = JSON.parse(ds._snap[round]); for (var _k in _s) { ds[_k] = _s[_k]; } }
            var _sk = ['cash','reputationTA','reputationGoogle','socialSentiment','bookingsNextMonth','totalRecoveryCost','reputationHistory','bookingHistory','sentimentHistory'];
            var _so = {}; for (var _i = 0; _i < _sk.length; _i++) { _so[_sk[_i]] = ds[_sk[_i]]; }
            ds._snap[round] = JSON.stringify(_so);
            var strat = d.strategy;
            var budget = d.budget;

            var repChange = 0;
            var sentChange = 0;
            var bookChange = 0;
            var budgetMult = Math.min(budget / 10000, 1.5);

            if (round === 1) {
                if (strat === 'A') {
                    repChange = 0.02 + (budgetMult * 0.03);
                    sentChange = 3 + Math.round(budgetMult * 5);
                    bookChange = -2;
                } else if (strat === 'B') {
                    repChange = -0.03;
                    sentChange = -5;
                    bookChange = -5;
                } else if (strat === 'C') {
                    repChange = -0.05;
                    sentChange = -8;
                    bookChange = -7;
                } else if (strat === 'D') {
                    repChange = -0.12;
                    sentChange = -18;
                    bookChange = -14;
                } else if (strat === 'E') {
                    repChange = 0.04 + (budgetMult * 0.04);
                    sentChange = 6 + Math.round(budgetMult * 6);
                    bookChange = -1;
                }
            } else if (round === 2) {
                if (strat === 'A') {
                    repChange = -0.08;
                    sentChange = -10;
                    bookChange = -8;
                } else if (strat === 'B') {
                    repChange = -0.15;
                    sentChange = -22;
                    bookChange = -15;
                } else if (strat === 'C') {
                    var compCost = 9000;
                    repChange = 0.05 + (budgetMult * 0.02);
                    sentChange = 12 + Math.round(budgetMult * 4);
                    bookChange = 3;
                    budget = Math.max(budget, compCost);
                } else if (strat === 'D') {
                    var recCost = 12600;
                    repChange = 0.08 + (budgetMult * 0.03);
                    sentChange = 18 + Math.round(budgetMult * 5);
                    bookChange = 5;
                    budget = Math.max(budget, recCost);
                } else if (strat === 'E') {
                    var luck = 0.7 + (Math.random() * 0.3);
                    repChange = 0.06 * luck + (budgetMult * 0.04);
                    sentChange = Math.round(15 * luck);
                    bookChange = Math.round(4 * luck);
                }
            } else if (round === 3) {
                if (strat === 'A') {
                    repChange = 0.02 + (budgetMult * 0.01);
                    sentChange = 3;
                    bookChange = 5 + Math.round(budgetMult * 3);
                } else if (strat === 'B') {
                    repChange = 0.01;
                    sentChange = 2;
                    bookChange = 8 + Math.round(budgetMult * 4);
                } else if (strat === 'C') {
                    repChange = 0.04 + (budgetMult * 0.02);
                    sentChange = 10 + Math.round(budgetMult * 5);
                    bookChange = 3;
                } else if (strat === 'D') {
                    repChange = 0.06 + (budgetMult * 0.02);
                    sentChange = 8 + Math.round(budgetMult * 4);
                    bookChange = 10 + Math.round(budgetMult * 5);
                } else if (strat === 'E') {
                    repChange = 0.03 + (budgetMult * 0.02);
                    sentChange = 15 + Math.round(budgetMult * 5);
                    bookChange = 6 + Math.round(budgetMult * 3);
                }
            } else if (round === 4) {
                if (strat === 'A') {
                    repChange = 0.05 + (budgetMult * 0.02);
                    sentChange = 5;
                    bookChange = 4;
                } else if (strat === 'B') {
                    repChange = 0.02;
                    sentChange = 3;
                    bookChange = 2;
                } else if (strat === 'C') {
                    repChange = 0.03;
                    sentChange = 4;
                    bookChange = 3;
                } else if (strat === 'D') {
                    repChange = 0.06 + (budgetMult * 0.02);
                    sentChange = 6 + Math.round(budgetMult * 3);
                    bookChange = 6 + Math.round(budgetMult * 2);
                } else if (strat === 'E') {
                    repChange = 0.10 + (budgetMult * 0.03);
                    sentChange = 10 + Math.round(budgetMult * 5);
                    bookChange = 10 + Math.round(budgetMult * 4);
                }
            }

            ds.reputationTA = Math.round(Math.max(1, Math.min(5, ds.reputationTA + repChange)) * 100) / 100;
            ds.reputationGoogle = Math.round(Math.max(1, Math.min(5, ds.reputationGoogle + (repChange * 0.8))) * 100) / 100;
            ds.socialSentiment = Math.max(0, Math.min(100, ds.socialSentiment + sentChange));
            ds.bookingsNextMonth = Math.max(0, Math.round(ds.bookingsNextMonth + bookChange));
            ds.cash = Math.round(ds.cash - budget);
            ds.totalRecoveryCost = Math.round(ds.totalRecoveryCost + budget);

            var baseMonthlyRevenue = 242000;
            var repMultiplier = ds.reputationTA / 4.7;
            var projectedRevenue = Math.round(baseMonthlyRevenue * repMultiplier);
            var revenueDelta = projectedRevenue - baseMonthlyRevenue;

            ds.reputationHistory.push(ds.reputationTA);
            ds.bookingHistory.push(ds.bookingsNextMonth);
            ds.sentimentHistory.push(ds.socialSentiment);

            var _score = this._computeScore(ds.reputationTA, ds.socialSentiment, ds.bookingsNextMonth, ds.totalRecoveryCost);
            ds.performance = { overallScore: _score, grade: this._gradeFor(_score), tier: this._tierFor(_score) };

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: state.currentPeriod,
                strategy: strat,
                budget: budget,
                reputationTA: ds.reputationTA,
                reputationGoogle: ds.reputationGoogle,
                socialSentiment: ds.socialSentiment,
                bookingsNextMonth: ds.bookingsNextMonth,
                projectedRevenue: projectedRevenue,
                revenueDelta: revenueDelta,
                cash: ds.cash,
                overallScore: ds.performance.overallScore,
                grade: ds.performance.grade,
                performanceTier: ds.performance.tier
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('reputationDisplay', 'domainState.reputationTA',
