        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastRep = history[history.length - 1].results ? history[history.length - 1].results.reputationTA : 4.6;
            var lastSent = history[history.length - 1].results ? history[history.length - 1].results.socialSentiment : 35;
            var lastBook = history[history.length - 1].results ? history[history.length - 1].results.bookingsNextMonth : 75;
            var totalSpent = 0;
            for (var i = 0; i < history.length; i++) {
                totalSpent += (history[i].results ? history[i].results.budget : 0);
            }

            var score = this._computeScore(lastRep, lastSent, lastBook, totalSpent);
            var tier = this._tierFor(score);

            var insights = [];
            if (lastRep >= 4.6) insights.push(this._t('insight_rep_full'));
            else if (lastRep >= 4.3) insights.push(this._t('insight_rep_partial'));
            else insights.push(this._t('insight_rep_low'));
            if (lastSent >= 60) insights.push(this._t('insight_sent_high'));
            else insights.push(this._t('insight_sent_low'));
            if (totalSpent > 60000) insights.push(this._t('insight_cost_high'));

            return {
                finalRating: lastRep,
                finalSentiment: lastSent,
                finalBookings: lastBook,
                totalInvested: totalSpent,
                score: score,
                overallScore: score,
                grade: this._gradeFor(score),
                performanceTier: tier,
                performance: this._t('perf_' + tier),
                insights: insights,
                totalPeriods: history.length
            };
        }

        formatCompletionMessage(summary) {
            var t = this._t.bind(this);
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore : (summary.score || 0);
            var tier = summary.performanceTier || this._tierFor(score);
            var verdict = summary.performance || this._t('perf_' + tier);
            var grade = summary.grade || this._gradeFor(score);
            var colors = { excellent: '#7ec98f', good: '#f0c674', adequate: '#6ca0dc', needs_improvement: '#e08a8a' };
            var color = colors[tier] || '#f0c674';
            var ins = '';
            if (summary.insights && summary.insights.length) {
                ins = '<div class="copan-cm-insights"><div class="copan-cm-insights-title">' + t('insights_label') + '</div><ul>';
                for (var i = 0; i < summary.insights.length; i++) ins += '<li>' + summary.insights[i] + '</li>';
                ins += '</ul></div>';
            }
            return '<div class="copan-cm">' +
                '<div class="copan-cm-title">' + t('completion_title') + '</div>' +
                '<div class="copan-cm-score-ring" style="border-color:' + color + '"><div class="copan-cm-score" style="color:' + color + '">' + score + '</div><div class="copan-cm-score-max">/ 100</div></div>' +
                '<div class="copan-cm-verdict" style="color:' + color + '">' + verdict + ' <span class="copan-cm-grade">(' + t('grade_label') + ' ' + grade + ')</span></div>' +
                '<div class="copan-cm-metrics">' +
                    '<div class="copan-cm-metric"><div class="copan-cm-metric-label">' + t('reputation_label') + '</div><div class="copan-cm-metric-value">' + (summary.finalRating || 0).toFixed(2) + '</div></div>' +
                    '<div class="copan-cm-metric"><div class="copan-cm-metric-label">' + t('sentiment_label') + '</div><div class="copan-cm-metric-value">' + Math.round(summary.finalSentiment || 0) + '%</div></div>' +
                    '<div class="copan-cm-metric"><div class="copan-cm-metric-label">' + t('bookings_label') + '</div><div class="copan-cm-metric-value">' + Math.round(summary.finalBookings || 0) + '</div></div>' +
                    '<div class="copan-cm-metric"><div class="copan-cm-metric-label">' + t('total_invested_label') + '</div><div class="copan-cm-metric-value">$' + Math.round(summary.totalInvested || 0).toLocaleString() + '</div></div>' +
                '</div>' + ins + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.reputationTA < 4.0) return window.mySimulation.t('hint_rep_critical');
            if (results.reputationTA < 4.3) return window.mySimulation.t('hint_rep_low');
            if (results.socialSentiment < 25) return window.mySimulation.t('hint_sentiment_low');
            if (results.bookingsNextMonth < 60) return window.mySimulation.t('hint_bookings_low');
            if (results.reputationTA >= 4.6 && results.socialSentiment >= 60) return window.mySimulation.t('hint_recovery_good');
            return null;
        }

